import sys
from collections import defaultdict
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
FIPI = 'https://doc.fipi.ru/{ex}/demoversii-specifikacii-kodifikatory/{y}/{f}'
FIPI_LIC = ('© ФИПИ / Рособрнадзор, «Все права защищены» (подвал fipi.ru; колонтитул PDF). Открытой лицензии нет. '
            'Используем только факты о структуре (номер, тип, баллы, коды) и ссылки; тексты заданий не копируем.')


def src(title, url, date, lic=FIPI_LIC):
    return {'title': title, 'url': url, 'date': date, 'license': lic}


def T(n, title, checks, codifier, answer, points, part, cards, gen, recipe, mistakes, theory, estimate, priority, examples,
      note=None):
    t = {'n': n, 'title': title, 'checks': checks, 'codifier': codifier, 'answer': answer, 'points': points, 'part': part,
         'cards': cards, 'gen': gen, 'recipe': recipe, 'mistakes': mistakes, 'theory': theory, 'estimate': estimate,
         'priority': priority, 'examples': examples}
    if note:
        t['note'] = note
    return t


def ex(q, a, o=None):
    e = {'q': q, 'a': a}
    if o:
        e['o'] = o
    return e


