def load_selfcheck():
    r = subprocess.run([sys.executable, str(ROOT / 'tools/research/gen_bio_geo.py')], capture_output=True, text=True, cwd=ROOT)
    return r.stdout.strip(), r.returncode


EXAMS = [EGE_BIO, OGE_BIO, EGE_GEO, OGE_GEO]


def build_json():
    out = []
    for e in EXAMS:
        d = {k: v for k, v in e.items() if k != 'tasks'}
        d['tasks'] = e['tasks']
        subj = e['subject']
        topics = TOPICS_BIO if subj == 'биология' else TOPICS_GEO
        d['topics_5_9'] = [{'grade': g, 'topic': t, 'cards': c, 'gen': gen, 'estimate': est} for g, t, c, gen, est in topics]
        d['topics_5_9_sources'] = SRC_59
        out.append(d)
    return out


