def md_exam(e):
    s = io.StringIO()
    w = s.write
    w(f"### {e['exam']}: {e['subject']}\n\n{e['summary']}\n\n**Оценивание.** {e['scoring']}\n\n")
    w('| № | Что проверяет | Ответ | Баллы | Карточка | Способ | Карточек | Приоритет |\n|---|---|---|---|---|---|---|---|\n')
    for t in e['tasks']:
        note = f" ⚠ {t['note']}" if t.get('note') else ''
        w(f"| {t['n']} | **{t['title']}.** {t['checks']}{note} | {ANS_RU[t['answer']]} | {t['points']} | "
          f"{', '.join('`' + c + '`' for c in t['cards'])} | {t['gen']} | {t['estimate']} | {t['priority']} |\n")
    tot = defaultdict(int)
    for t in e['tasks']:
        tot[t['gen']] += t['estimate']
    w('\nИтого по способам: ' + ', '.join(f'{k} — {v}' for k, v in sorted(tot.items(), key=lambda x: -x[1]))
      + f" (всего ≈ {sum(tot.values())}).\n\n")
    w('<details><summary>Рецепты, типичные ошибки, теория, свои примеры</summary>\n\n')
    for t in e['tasks']:
        w(f"**{t['n']}. {t['title']}** (кодификатор: {', '.join(t['codifier'])}; часть {t['part']})\n\n")
        w(f"- Рецепт: {t['recipe']}\n- Ошибки: {'; '.join(t['mistakes'])}\n- Теория: {'; '.join(t['theory'])}\n")
        for x in t['examples']:
            o = f" Варианты: {' / '.join(x['o'])}." if x.get('o') else ''
            w(f"- Пример: {x['q']}{o} → **{x['a']}**\n")
        w('\n')
    w('</details>\n\n')
    return s.getvalue()


def md_sources(e):
    return ''.join(f"- {x['title']} — {x['url']} (дата документа: {x['date']})\n" for x in e['sources'])


def build_md(selfcheck):
    s = io.StringIO()
    w = s.write
    allt = [(e, t) for e in EXAMS for t in e['tasks']]
    by_gen = defaultdict(int)
    for _, t in allt:
        by_gen[t['gen']] += t['estimate']
    top = '; '.join(f"{e['exam'][:3]} {'био' if e['subject'] == 'биология' else 'гео'} "
                    + ', '.join(str(t['n']) for t in e['tasks'] if t['priority'] == 1 and t['gen'] == 'param') for e in EXAMS)
    w('# Биология и география: ЕГЭ 2026, ОГЭ 2026, 5–9 класс — как делать карточки массово\n\n')
    w('_Исследование для «Между уроками». Данные: `data/research/bio-geo.json`; генераторы: `tools/research/gen_bio_geo.py`; '
      'отчёт и JSON собирает `tools/research/bio_geo_research.py`. Дата: 27.09.2026._\n\n')
    w('## Коротко\n\n')
    w('- **Структура 2026 (ФИПИ, документы от 5–6 ноября 2025).** ЕГЭ биология: 28 заданий, 57 баллов. ОГЭ биология: 26 заданий, 47 баллов. '
      'ЕГЭ география: 29 заданий, 38 баллов. ОГЭ география: 30 заданий, 31 балл. Против 2025 г. содержание не менялось; '
      'в ОГЭ по географии перенумерованы задания 19–30. В КИМ 2027 (август 2026) по биологии ЕГЭ перераспределены баллы: 21 → 1, 26 → 4.\n')
    w(f"- **Сколько карточек реально сделать:** около {sum(by_gen.values()):,} на четыре экзамена ".replace(',', ' ')
      + '(' + ', '.join(f'{k} — {v:,}'.replace(',', ' ') for k, v in sorted(by_gen.items(), key=lambda x: -x[1])) + '). '
      'Для `param` это ёмкость генераторов (сколько разных задач они дают), для `dict` — объём словарей, которые реально собрать за 1–2 недели. '
      'Плюс 5–9 класс: ≈ ' + f"{sum(x[4] for x in TOPICS_BIO + TOPICS_GEO):,}".replace(',', ' ') + '. '
      'Готово уже сейчас: 29 генераторов × 200 = 5 800 проверенных карточек.\n')
    w('- **Генераторы работают.** 29 генераторов в `tools/research/gen_bio_geo.py` покрывают расчётные и «порядковые» задания: '
      'ЕГЭ био 3, 4, 12, 27, 28 (шаги); ОГЭ био 3, 19–21, 26; ЕГЭ гео 2, 3, 4, 14, 15, 16, 27, 28; ОГЭ гео 9, 10, 13, 17, 24, 26. '
      'Самопроверка: 200 уникальных карточек на тип, ответ пересчитан вторым независимым способом — 0 ошибок.\n')
    w('- **Начать с** (приоритет 1, вычисляемые: генератор готов или нужны только открытые данные): ' + top + '. Затем словари для соответствий и множественного выбора по биологии '
      '(ЕГЭ 6–8, 10–12, 14–16, 18–19 — 22 из 39 баллов части 1; ОГЭ 2, 8, 9, 11, 15, 17, 18).\n')
    w('- **Что мешает:** нет типов карточек «ввод слова» и «последовательность» (см. «Риски»); задания с рисунками требуют своих изображений; '
      'тексты ФИПИ под «Все права защищены» — копировать нельзя, только структура и свои примеры.\n\n')

    w('## Формат карточек\n\nКарточки в формате наборов (`tools/build_packs.py`): `one`, `many`, `match`, `flip`, `open`, `stress`, `num`. '
      'Способы генерации: **param** — вычисляемые задачи (ответ считает код); **dict** — из проверенных словарей фактов; '
      '**llm** — ИИ по прототипу с проверкой; **bank** — нужны внешние материалы (картинки, карты). '
      'Приоритет: 1 — делать сразу, 2 — во вторую очередь, 3 — по остаточному принципу. Оценка «Карточек» — сколько качественных '
      'разных карточек реально получить (для `param` — с запасом ниже ёмкости генератора).\n\n')
    w('## Экзамены\n\n')
    for e in EXAMS:
        w(md_exam(e))
    w('## 5–9 класс (ФРП ООО 2025, базовый уровень)\n\n')
    for subj, topics in (('биология', TOPICS_BIO), ('география', TOPICS_GEO)):
        w(f'### {subj.capitalize()}\n\n{USEFUL_59[subj]}\n\n| Класс | Тема (раздел ФРП) | Карточки | Способ | Карточек |\n|---|---|---|---|---|\n')
        for g, t, c, gen, est in topics:
            w(f"| {g} | {t} | {', '.join('`' + x + '`' for x in c)} | {gen} | {est} |\n")
        w(f"\nИтого ≈ {sum(x[4] for x in topics):,}.\n\n".replace(',', ' '))
    w('Разделы — по тематическому планированию ФРП (edsoo.ru, 2025). Часы и формулировки сверены по PDF; '
      'деление на темы внутри раздела — наше, для карточек.\n\n')
    w('## Прототипы генераторов и самопроверка\n\n')
    w('`python3 tools/research/gen_bio_geo.py` — для каждого типа генерируется 200 **уникальных** карточек (по тексту вопроса и вариантам), '
      'ответ каждой пересчитывается функцией `check_<тип>` другим способом (решётка Пеннета перебором вместо формулы, `datetime` для часовых зон, '
      'моделирование гамет, поиск в глубину по пищевой сети, формула длины дня вместо правила «севернее/южнее» и т. д.). '
      '«Различных по сути» — число разных задач без учёта имён организмов/городов; «ёмкость» — сколько разных вариантов даёт 3000 попыток.\n\n')
    w(selfcheck + '\n\n')
    w('Примеры: `python3 tools/research/gen_bio_geo.py --sample b_transcr 3`; выгрузка всего: `--dump out.json`. '
      'Поле `chk` (параметры для проверки) при сборке наборов надо убрать; `p` (прототип) — проставить по заданию.\n\n')
    w('## Источники\n\n')
    for e in EXAMS:
        w(f"**{e['exam']}, {e['subject']}**\n\n" + md_sources(e) + '\n')
    w('**5–9 класс**\n\n' + ''.join(f"- {x['title']} — {x['url']} ({x['date']})\n" for x in SRC_59) + '\n')
    w('Даты документов ФИПИ — по метаданным PDF (дата создания; в скобках — изменения). Все PDF скачаны с doc.fipi.ru 27.09.2026.\n\n')
    w('### Лицензии и что можно брать\n\n| Источник | Условия | Статус |\n|---|---|---|\n')
    for name, url, cond, st in LICENSES:
        w(f'| [{name}]({url}) | {cond} | {st} |\n' if url != '—' else f'| {name} | {cond} | {st} |\n')
    w('\n## Риски\n\n' + ''.join(f'{i}. {r}\n' for i, r in enumerate(RISKS, 1)))
    w('\n## Что осталось\n\n- Собрать словари `dict` (биология: органоиды, таксоны, органы человека, ~2–3 тыс. утверждений; география: '
      'города/субъекты/страны из Wikidata и Росстата) и выгрузку данных World Bank/UN.\n'
      '- Генераторы для ЕГЭ био 21 и ОГЭ гео 16 (таблица + вычисляемые утверждения), ОГЭ гео 8 (разрез), полная задача ЕГЭ био 28 с текстовым решением.\n'
      '- Подсчитать прототипы в открытом банке ФИПИ (не открылся из среды).\n'
      '- Типы карточек `word` и `seq`/`order` — отдельный PR в `lib.js`.\n')
    return s.getvalue()


def main():
    selfcheck, code = load_selfcheck()
    if code:
        print('Самопроверка генераторов не прошла:\n' + selfcheck, file=sys.stderr)
        sys.exit(1)
    data = build_json()
    (ROOT / 'data/research').mkdir(parents=True, exist_ok=True)
    (ROOT / 'docs/research').mkdir(parents=True, exist_ok=True)
    (ROOT / 'data/research/bio-geo.json').write_text(json.dumps(data, ensure_ascii=False, indent=1), 'utf-8')
    (ROOT / 'docs/research/bio-geo.md').write_text(build_md(selfcheck), 'utf-8')
    n = sum(len(e['tasks']) for e in data)
    print(f'data/research/bio-geo.json: {len(data)} экзамена, {n} заданий; docs/research/bio-geo.md')


if __name__ == '__main__':
    main()
